mapper.select:
select  from nad_applicant


        and (given_name like concat('%', #{name}, '%') or family_name like concat('%', #{name}, '%'))

    and status = #{status}
    and nationality = #{nationality}

order by family_name, given_name, id

mapper.update:
update nad_applicant set
    given_name = #{givenName}, family_name = #{familyName}, dob = #{dob},
    nationality = #{nationality}, passport_no = #{passportNo}, email = #{email}, phone = #{phone},
    update_by = #{updateBy}, update_time = now(), remark = #{remark}
where id = #{id}

update nad_applicant_contact set
    relation = #{relation}, name = #{name}, email = #{email}, phone = #{phone}, update_time = now()
where id = #{id} and applicant_id = #{applicantId}
